$('#authForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const form = e.currentTarget;
  const mode = form.dataset.mode === 'setup' ? 'setup' : 'login';
  const data = new FormData(form);
  const payload = {
    email: String(data.get('email') || '').trim().toLowerCase(),
    password: String(data.get('password') || '')
  };
  if (mode === 'setup') {
    payload.full_name = String(data.get('full_name') || '').trim();
    payload.organization_name = String(data.get('organization_name') || '').trim();
    payload.timezone = 'Asia/Hebron';
  }
  const button = $('#authSubmit');
  button.disabled = true;
  button.textContent = 'جارٍ التحقق…';
  $('#authMessage').innerHTML = '';
  authTransitionInProgress = true;
  try {
    const out = await api('/auth/' + (mode === 'setup' ? 'setup' : 'login'), {
      method: 'POST',
      body: JSON.stringify(payload)
    });
    if (!out || typeof out.access_token !== 'string' || !out.access_token || !out.user) {
      throw new Error('استجاب الخادم دون بيانات جلسة مكتملة. لم يتم حفظ تسجيل الدخول.');
    }
    token = out.access_token;
    sessionStorage.setItem('midar_token', token);
    currentUser = out.user;
    try {
      // Verify the token before switching away from the authentication screen.
      currentUser = await api('/auth/me');
      await enterApp();
    } catch (sessionError) {
      token = '';
      currentUser = null;
      sessionStorage.removeItem('midar_token');
      $('#appShell').classList.add('hidden');
      $('#authScreen').classList.remove('hidden');
      throw new Error('تم قبول بيانات الدخول، لكن تعذر تهيئة جلسة المنصة. ' + (sessionError?.message || 'تحقق من سجل الخادم.'));
    }
  } catch (err) {
    token = '';
    currentUser = null;
    sessionStorage.removeItem('midar_token');
    $('#authScreen').classList.remove('hidden');
    $('#appShell').classList.add('hidden');
    $('#authMessage').innerHTML = `<div class="error" role="alert">${esc(err?.message || 'تعذر تسجيل الدخول. تحقق من الاتصال وحاول مجددًا.')}</div>`;
  } finally {
    authTransitionInProgress = false;
    button.disabled = false;
    button.textContent = mode === 'setup' ? 'إنشاء مساحة العمل' : 'تسجيل الدخول';
  }
});
