function isAppleTouchDevice(){return /iPhone|iPad|iPod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1)}
function setMobileSidebarOpen(open,options={}){
  const mobile=window.matchMedia('(max-width: 760px)').matches;
  const sidebar=$('#sidebar'),overlay=$('#mobileOverlay'),menu=$('#menuBtn');
  const wasOpen=sidebar.classList.contains('open');
  const shouldOpen=Boolean(open&&mobile);
  if(shouldOpen&&!wasOpen){
    mobileNavScrollY=window.scrollY||window.pageYOffset||0;
    if(isAppleTouchDevice()){
      mobileNavBodyStyles={position:document.body.style.position,top:document.body.style.top,width:document.body.style.width};
      document.body.style.position='fixed';
      document.body.style.top=`-${mobileNavScrollY}px`;
      document.body.style.width='100%';
    }
  }
  sidebar.classList.toggle('open',shouldOpen);
  overlay.classList.toggle('open',shouldOpen);
  document.body.classList.toggle('mobile-nav-open',shouldOpen);
  menu.setAttribute('aria-expanded',String(shouldOpen));
  menu.setAttribute('aria-label',shouldOpen?'إغلاق القائمة':'فتح القائمة');
  overlay.setAttribute('aria-hidden',String(!shouldOpen));
  if(shouldOpen){
    sidebar.removeAttribute('aria-hidden');
    sidebar.inert=false;
    sidebar.setAttribute('role','dialog');
    sidebar.setAttribute('aria-modal','true');
    sidebar.setAttribute('aria-label','قائمة التنقل الرئيسية');
    requestAnimationFrame(()=>{
      const target=sidebar.querySelector('#nav button.active:not(.hidden), #nav button:not(.hidden)');
      if(target)target.focus({preventScroll:true});
    });
  }else{
    sidebar.removeAttribute('aria-modal');
    sidebar.removeAttribute('role');
    if(mobile){sidebar.setAttribute('aria-hidden','true');sidebar.inert=true}
    else{sidebar.removeAttribute('aria-hidden');sidebar.inert=false}
    if(wasOpen&&mobileNavBodyStyles){
      document.body.style.position=mobileNavBodyStyles.position;
      document.body.style.top=mobileNavBodyStyles.top;
      document.body.style.width=mobileNavBodyStyles.width;
      mobileNavBodyStyles=null;
      window.scrollTo(0,mobileNavScrollY);
    }
    if(wasOpen&&options.restoreFocus!==false)menu.focus({preventScroll:true});
  }
}
