async function shiftPostMonth(delta){postWorkspace.month+=delta;if(postWorkspace.month<0){postWorkspace.month=11;postWorkspace.year--}else if(postWorkspace.month>11){postWorkspace.month=0;postWorkspace.year++}await refreshPostCalendar()}
async function refreshPostCalendar(){const grid=$('#postCalendarGrid');if(grid)grid.innerHTML='<div class="cm-loading">جارٍ تحديث التقويم…</div>';try{await loadPostCalendar();const old=$('#postCalendarView');if(old){const shell=$('#pageContent');const focused=document.activeElement?.id;const keep=postWorkspace.view;const render=postCalendarMarkup();const tmp=document.createElement('div');tmp.innerHTML=render;const fresh=tmp.querySelector('#postCalendarGrid');if(fresh&&grid)grid.replaceWith(fresh);const backlogOld=document.querySelector('.cm-backlog-list'),backlogNew=tmp.querySelector('.cm-backlog-list');if(backlogOld&&backlogNew)backlogOld.innerHTML=backlogNew.innerHTML;const truncOld=shell.querySelector('.cm-truncation'),truncNew=tmp.querySelector('.cm-truncation');if(truncOld)truncOld.remove();if(truncNew)shell.querySelector('.cm-workspace').appendChild(truncNew);$('#cmMonthTitle').textContent=monthLabel(postWorkspace.year,postWorkspace.month);updatePostViews();if(focused&&document.getElementById(focused))document.getElementById(focused).focus()}}catch(e){if(grid)grid.innerHTML=`<div class="cm-loading cm-error">تعذر تحديث التقويم: ${esc(e.message)}</div>`;toast(e.message)}}
function postRows(xs){
  if(!xs.length)return blankRow(5,'لا توجد منشورات مطابقة.');
  return xs.map(x=>{
    const locked=['published','publishing','delivery_unknown','in_review','approved'].includes(x.status);
    const canReview=canWriteArea('posts')&&['draft','changes_requested','scheduled'].includes(x.status);
    const canDecide=['owner','admin'].includes(currentUser?.role)&&x.status==='in_review';
    const publishable=['Telegram','Facebook','X','LinkedIn'].includes(x.platform)&&['draft','scheduled','approved','failed'].includes(x.status);
    const reviewActions=canReview?`<button class="btn btn-small" data-submit-review="${esc(x.id)}">إرسال للمراجعة</button> `:'';
    const decisionActions=canDecide?`<button class="btn btn-small btn-primary" data-approve-post="${esc(x.id)}">اعتماد</button> <button class="btn btn-small" data-request-changes="${esc(x.id)}">طلب تعديل</button> `:'';
    const deliveryActions=x.status==='delivery_unknown'&&['owner','admin'].includes(currentUser?.role)?`<button class="btn btn-small" data-resolve-delivery="${esc(x.id)}" data-resolution="published">تأكيد النشر</button> <button class="btn btn-small" data-resolve-delivery="${esc(x.id)}" data-resolution="failed">تأكيد عدم النشر</button> `:'';
    const ordinaryActions=!locked?`<button class="btn btn-small" data-edit-post="${esc(x.id)}">تعديل</button> <button class="btn btn-small btn-danger" data-delete-post="${esc(x.id)}">حذف</button>`:'';
    const reviewNote=x.status==='changes_requested'&&x.review_note?`<div class="review-note" role="note"><b>ملاحظة المراجع:</b> ${esc(x.review_note)}</div>`:'';
    return `<tr><td><b>${esc(x.title)}</b><div class="muted" style="max-width:300px;overflow:hidden;text-overflow:ellipsis">${esc(x.content||'—')}</div>${reviewNote}${x.publish_error?`<div class="help" role="note">${esc(x.publish_error)}</div>`:''}</td><td><span class="platform">${esc(x.platform)}</span></td><td>${dateTime(x.scheduled_at)}</td><td>${badgeForPost(x.status)}</td><td>${canWriteArea('posts')?`${publishable?`<button class="btn btn-small btn-primary" data-publish-post="${esc(x.id)}">نشر الآن</button> `:''}${reviewActions}${decisionActions}${deliveryActions}${ordinaryActions}`:status('عرض فقط','muted')}</td></tr>`;
  }).join('');};function filterPosts(){const q=$('#postSearch').value.toLowerCase(),s=$('#postStatus').value,p=$('#postPlatform').value;$('#postsRows').innerHTML=postRows(cache.posts.filter(x=>(!q||(x.title+' '+x.content).toLowerCase().includes(q))&&(!s||x.status===s)&&(!p||x.platform===p)))}
