{const q=$('#taskSearch').value.toLowerCase(),s=$('#taskFilter').value;$('#tasksRows').innerHTML=taskRows(cache.tasks.filter(x=>(!q||(x.title+' '+x.description).toLowerCase().includes(q))&&(!s||x.status===s)))}
async function renderAccounts(){
  const isAdmin=['owner','admin'].includes(currentUser.role);
  const [accounts,catalog,adminStatus]=await Promise.all([
    api('/social-accounts'),
    api('/integrations/catalog'),
    isAdmin?api('/integrations/status'):Promise.resolve(null)
  ]);
  cache.accounts=accounts;
  const liveProviders=new Map((adminStatus?.providers||[]).map(p=>[p.platform,p]));
  const implementationLabels={partial:'موصل جزئي',planned:'قيد التطوير',implemented:'منفذ',manual_only:'سجل داخلي فقط'};
  const implementationKinds={partial:'warn',planned:'muted',implemented:'good',manual_only:'muted'};
  const platformCards=catalog.providers.filter(p=>p.platform!=='Other').map(p=>{
    const actual=liveProviders.get(p.platform);
    let label=implementationLabels[p.implementation_status]||'قيد التقييم';
    let kind=implementationKinds[p.implementation_status]||'muted';
    let detail=p.status_label_ar||'';
    if(p.platform==='Telegram'&&actual){
      if(actual.status==='ready'){label='جاهز للنشر النصي';kind='good';detail='تم إعداد رمز البوت والتحقق من وجهة نشر واحدة على الأقل.'}
      else if(actual.status==='configured_channel_verification_required'){label='الرمز موجود؛ يلزم التحقق';kind='warn';detail='تحقق من كل قناة قبل استخدام النشر الخارجي.'}
      else {label='يتطلب إعداد رمز البوت';kind='warn';detail='التكامل منفذ جزئيًا؛ لا يتوفر استقبال رسائل أو نشر وسائط أو جدولة خلفية.'}
    }
    const implemented=(p.implemented_capabilities||[]).map(x=>({verify_destination:'التحقق من وجهة النشر',publish_text:'نشر النص يدويًا',manual_record:'تسجيل داخلي فقط'}[x]||x));
    const planned=(p.planned_capabilities||[]);
    return `<article class="provider-card"><div class="provider-card-top"><div class="provider-symbol provider-${esc(p.platform.toLowerCase())}">${esc(({Facebook:'f',Instagram:'◎',WhatsApp:'◔',Telegram:'➤',X:'𝕏',YouTube:'▶',TikTok:'♪',LinkedIn:'in'}[p.platform]||'•'))}</div><div class="provider-heading"><h3>${esc(p.platform)}</h3><p>${esc(p.method)}</p></div>${status(label,kind)}</div><p class="provider-description">${esc(p.description_ar||'')}</p>${implemented.length?`<div class="provider-capabilities"><b>متاح في هذه النسخة</b><div class="capability-chips">${implemented.map(x=>`<span class="capability-chip is-live">${esc(x)}</span>`).join('')}</div></div>`:''}<div class="provider-capabilities"><b>${planned.length?'المخطط لاحقًا':'ملاحظات'}</b><div class="capability-chips">${(planned.length?planned:[p.limitations_ar||'لا توجد وظائف خارجية إضافية في هذا الإصدار']).map(x=>`<span class="capability-chip">${esc(x)}</span>`).join('')}</div></div><div class="provider-foot"><span class="help">${esc(p.limitations_ar||'')}</span>${p.docs_url?`<a class="provider-doc-link" href="${esc(p.docs_url)}" target="_blank" rel="noopener noreferrer">وثائق المطور <span aria-hidden="true">↗</span></a>`:''}</div></article>`;
  }).join('');
  const rows=accounts.length?accounts.map(a=>{
    const verifiedTelegram=a.platform==='Telegram'&&a.connection_status==='connected'&&Boolean(a.provider_account_id);
    const verifiedMeta=['Facebook','Instagram'].includes(a.platform)&&a.connection_status==='connected'&&Boolean(a.provider_account_id);
    const verifiedOAuth=['X','TikTok','YouTube','LinkedIn'].includes(a.platform)&&a.connection_status==='connected'&&Boolean(a.provider_account_id);
    const canReadRemoteContent=['X','TikTok','YouTube'].includes(a.platform);
    const state=verifiedMeta?status('متصل عبر Meta','good'):verifiedOAuth?status('متصل عبر OAuth','good'):verifiedTelegram?status('وجهة Telegram متحققة','good'):status('سجل محلي غير متحقق','warn');
    const mediaAction=verifiedMeta||(verifiedOAuth&&canReadRemoteContent)?'<button class="btn btn-small" data-view-remote-media="'+esc(a.id)+'">عرض المحتوى الحقيقي</button>':'';
    const telegramAction=a.platform==='Telegram'&&a.handle&&canWriteArea('accounts')?'<button class="btn btn-small" data-telegram-verify="'+esc(a.id)+'">تحقق من القناة</button>':'';
    const deleteAction=canWriteArea('accounts')?'<button class="btn btn-small btn-danger" data-delete-account="'+esc(a.id)+'">إزالة من القائمة</button>':'';
    const actions=[mediaAction,telegramAction,deleteAction].filter(Boolean).join(' ');
    return '<tr><td><span class="platform">'+esc(a.platform)+'</span></td><td><b>'+esc(a.account_name)+'</b></td><td>'+esc(a.handle||'—')+'</td><td>'+state+'</td><td>'+(actions||status('عرض فقط','muted'))+'</td></tr>';
  }).join(''):blankRow(5,'لم تضف حسابات بعد. إضافة سجل لا تعني الاتصال بالمنصة.');
  $('#pageContent').innerHTML=`${pageHead('الحسابات الاجتماعية','إدارة سجلات الحسابات ومراجعة حالة التكامل الحقيقي',canWriteArea('accounts')?'إضافة حساب':'','new-account')}<div class="notice"><b>شفافية حالة التكامل</b>تظهر البطاقات أدناه ما تم تنفيذه فعلًا وما لا يزال ضمن خارطة الطريق. إضافة حساب إلى القائمة لا تربطه بالمنصة تلقائيًا. لا تدخل رموز الوصول في حقول الحسابات.</div><div class="grid stats">${stat('حسابات مسجلة',accounts.length,'سجلات داخل مساحة العمل','◎')}${stat('حسابات Meta المتصلة',accounts.filter(a=>['Facebook','Instagram'].includes(a.platform)&&a.connection_status==='connected'&&a.provider_account_id).length,'بعد OAuth وصلاحيات المنصة','✓')}${stat('وجهات Telegram المتحققة',accounts.filter(a=>a.platform==='Telegram'&&a.connection_status==='connected'&&a.provider_account_id).length,'بعد تحقق Bot API فقط','➤')}${stat('منصات في الكتالوج',catalog.providers.filter(p=>p.platform!=='Other').length,'قابلة للتوسع تدريجيًا','＋')}</div><section class="card provider-section"><div class="card-head"><div><h3>خريطة قدرات المنصات</h3><p>الحالة مستقاة من سجل قدرات النظام، وليست وعدًا بوجود صلاحيات أو موافقات لدى حسابك.</p></div></div><div class="provider-grid">${platformCards}</div></section><section class="card" style="margin-top:16px"><div class="card-head"><div><h3>الحسابات المسجلة</h3><p>السجلات المرتبطة بمساحة العمل الحالية</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>المنصة</th><th>اسم الحساب</th><th>المعرّف الظاهر</th><th>حالة الربط</th><th>إجراءات</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
}
async function renderInbox(){const [conversations,contacts]=await Promise.all([api('/conversations'),canReadArea('contacts')?api('/contacts?limit=250'):Promise.resolve([])]);const names=new Map(contacts.map(c=>[c.id,c.name]));$('#pageContent').innerHTML=`${pageHead('صندوق الرسائل','محادثات WhatsApp Business الفعلية بعد التحقق؛ القنوات الأخرى محلية حتى توصيل موصلها',canWriteArea('inbox')?'محادثة جديدة':'','new-conversation')}<div class=\"notice\"><b>تنبيه تكاملات</b>يدعم M استقبال رسائل WhatsApp Business عبر Webhook موقّع وإرسال الردود النصية بعد التحقق من رقم الأعمال؛ سجلات القنوات الأخرى لا تُرسل إلى المنصات.</div><section class=\"card\"><div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>القناة</th><th>العميل</th><th>الحالة</th><th>آخر نشاط</th><th>إجراء</th></tr></thead><tbody>${conversations.length?conversations.map(c=>`<tr><td><span class=\"platform\">${esc(c.channel)}</span></td><td>${esc(names.get(c.contact_id)||'بدون عميل مرتبط')}</td><td>${status(({open:'مفتوحة',pending:'بانتظار المتابعة',closed:'مغلقة'})[c.status]||c.status,c.status==='open'?'good':c.status==='pending'?'warn':'muted')}</td><td>${dateTime(c.last_message_at||c.created_at)}</td><td><button class=\"btn btn-small\" data-open-conversation=\"${esc(c.id)}\">فتح السجل</button></td></tr>`).join(''):blankRow(5,'لا توجد سجلات محادثات بعد.')}</tbody></table></div></section>`}async function renderConversationDetail(conversationId){const [conversations,messages]=await Promise.all([api('/conversations'),api('/conversations/'+conversationId+'/messages')]);const conversation=conversations.find(c=>c.id===conversationId);if(!conversation){toast('المحادثة غير موجودة');return renderInbox()}const contacts=canReadArea('contacts')?await api('/contacts?limit=250'):[];const contact=contacts.find(c=>c.id===conversation.contact_id);$('#topTitle').textContent='تفاصيل المحادثة';$('#topSubtitle').textContent=conversation.channel==='WhatsApp'?'WhatsApp Business — الرسائل الواردة والردود النصية الفعلية':'سجل داخلي غير متصل بالمنصة الخارجية';const history=messages.length?messages.map(m=>`<article class=\"message-entry\"><div class=\"message-meta\"><b>${m.direction==='inbound'?'وارد من المنصة':m.delivery_status==='sent'?'أُرسل عبر المنصة':m.delivery_status==='delivery_unknown'?'نتيجة الإرسال غير مؤكدة':'سجل صادر محلي'}</b><span>${dateTime(m.created_at)}</span>${status(m.delivery_status==='local_only'?'محلي فقط':m.delivery_status,'muted')}</div><p>${esc(m.body)}</p></article>`).join(''):`<div class=\"empty-box\">لا يوجد سجل رسائل في هذه المحادثة.</div>`;$('#pageContent').innerHTML=`${pageHead(contact?.name||'محادثة '+conversation.channel,(conversation.channel==='WhatsApp'?'يدعم هذا السجل الرسائل الواردة الفعلية وردود النص عبر WhatsApp Business بعد التحقق والإعداد.':'هذه الصفحة تحتفظ بسجل محلي فقط؛ الإرسال الخارجي لهذه القناة غير مفعّل.'), 'العودة للصندوق','back-inbox')}<div class=\"grid two-col\"><section class=\"card\"><div class=\"card-head\"><div><h3>سجل المحادثة</h3><p>${esc(conversation.channel)} · ${esc(contact?.email||contact?.phone||'لا توجد بيانات اتصال')}</p></div></div><div class=\"message-list\">${history}</div><form id=\"localMessageForm\" data-conversation-id=\"${esc(conversation.id)}\" class=\"local-message-form\"><div class=\"field full\"><label for=\"localMessageBody\">${conversation.channel==='WhatsApp'?'إرسال رد WhatsApp':'إضافة سجل رسالة محلي'}</label><textarea id=\"localMessageBody\" name=\"body\" required maxlength=10000 placeholder=\"${conversation.channel==='WhatsApp'?'اكتب ردّك لإرساله إلى العميل عبر WhatsApp…':'دوّن رسالة أو مسودة محلية للرجوع إليها…'}\"></textarea></div><div class=\"help\">${conversation.channel==='WhatsApp'?'سيُرسل النص فعليًا من رقم WhatsApp Business المتحقق؛ تخضع الرسائل لقواعد Meta ونافذة خدمة العملاء.':'يُحفظ النص محليًا فقط ولا يتم إرساله إلى المنصة الخارجية.'}</div><button class=\"btn btn-primary\" type=\"submit\">${conversation.channel==='WhatsApp'?'إرسال الرسالة':'حفظ السجل المحلي'}</button></form></section><section class=\"card\"><div class=\"card-head\"><div><h3>حالة المتابعة</h3><p>تغيير حالة السجل داخل المنصة</p></div></div><div class=\"form-grid\"><div class=\"field full\"><label for=\"conversationStatus\">الحالة</label><select id=\"conversationStatus\" class=\"field-input\" data-conversation-status=\"${esc(conversation.id)}\"><option value=\"open\" ${conversation.status==='open'?'selected':''}>مفتوحة</option><option value=\"pending\" ${conversation.status==='pending'?'selected':''}>بانتظار المتابعة</option><option value=\"closed\" ${conversation.status==='closed'?'selected':''}>مغلقة</option></select></div><div class=\"field full\"><label>القناة</label><input value=\"${esc(conversation.channel)}\" disabled></div><div class=\"field full\"><label>معرّف السجل</label><input value=\"${esc(conversation.id)}\" disabled></div></div></section></div>`}
async function renderAudit(){const rows=await api('/audit-logs?limit=200');const detailText=x=>{const d=x.details||{};return d.note?`ملاحظة المراجع: ${d.note}`:d.title?`العنوان: ${d.title}`:d.previous_status?`الحالة السابقة: ${postStatusLabel(d.previous_status)}`:'—'};$('#pageContent').innerHTML=`${pageHead('سجل النشاط','تسجيل تغييرات البيانات والقرارات المهمة')}<section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>الوقت</th><th>الإجراء</th><th>نوع السجل</th><th>التفاصيل</th><th>معرّف السجل</th><th>المستخدم</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${dateTime(x.created_at)}</td><td>${esc(x.action)}</td><td>${esc(x.entity_type)}</td><td>${esc(detailText(x))}</td><td>${esc(x.entity_id||'—')}</td><td>${esc(x.user_id===currentUser.id?currentUser.full_name:x.user_id)}</td></tr>`).join(''):blankRow(6,'لا توجد عمليات مسجلة بعد.')}</tbody></table></div></section>`}

const renderAccountsLegacy = renderAccounts;
renderAccounts = async function() {
  await renderAccountsLegacy();
  if (!currentUser || !['owner', 'admin'].includes(currentUser.role)) return;
  const area = document.querySelector('#pageContent');
  if (!area) return;
  let config = { enabled: false, token_vault_ready: false, api_version: 'v26.0' };
  try { config = await api('/integrations/meta/config', { headers: {} }); } catch (_) {}
  const banner = document.createElement('section');
  banner.className = 'meta-connection-banner';
  const copy = document.createElement('div');
  const title = document.createElement('h3');
  title.textContent = 'ربط الحسابات الفعلية';
  const desc = document.createElement('p');
  desc.textContent = 'اربط صفحات Facebook التي تديرها وحسابات Instagram الاحترافية المرتبطة بها، ثم افتح منشوراتك وفيديوهاتك والريلز التي تسمح بها واجهة Meta الرسمية.';
  const detail = document.createElement('p');
  detail.className = 'meta-config-line';
  detail.textContent = config.enabled
    ? 'إعداد OAuth موجود · Graph API ' + (config.api_version || '') + (config.token_vault_ready ? ' · خزنة الرموز جاهزة' : ' · يلزم تجهيز مفتاح التشفير')
    : 'يلزم إعداد META_APP_ID وMETA_APP_SECRET وMETA_REDIRECT_URI في ملف إعدادات M.';
  copy.append(title, desc, detail);
  const connect = document.createElement('button');
  connect.type = 'button';
  connect.className = 'btn btn-primary';
  connect.dataset.action = 'connect-meta';
  connect.textContent = 'ربط Facebook وInstagram';
  banner.append(copy, connect);
  const notice = area.querySelector('.notice');
  if (notice) notice.insertAdjacentElement('beforebegin', banner); else area.prepend(banner);
};
function safeHttpsMediaUrl(value) {
  try { const url = new URL(String(value || '')); return url.protocol === 'https:' ? url.href : ''; }
  catch (_) { return ''; }
}

async function renderMetaMedia(accountId) {
  const account=(cache.accounts||[]).find(item=>item.id===accountId);
  const metaMedia=['Facebook','Instagram'].includes(account?.platform);
  const providerKey=({X:'x',TikTok:'tiktok',YouTube:'youtube'})[account?.platform]||'';
  if(!account||(!metaMedia&&!providerKey)){toast('هذا الحساب لا يملك موصل قراءة محتوى منفذًا في هذه النسخة');return}
  const content=document.querySelector('#pageContent');if(!content)return;
  const loading=document.createElement('section');loading.className='card empty-box';loading.setAttribute('role','status');
  const loadingTitle=document.createElement('b');loadingTitle.textContent='جاري جلب المحتوى الحقيقي';
  const loadingText=document.createElement('p');loadingText.textContent='يتصل M بواجهة المنصة الرسمية؛ لا تُعرض هنا منشورات تجريبية.';loading.append(loadingTitle,loadingText);content.replaceChildren(loading);
  try {
    const endpoint=metaMedia?('/integrations/meta/accounts/'+encodeURIComponent(accountId)+'/media'):(`/integrations/oauth/${providerKey}/accounts/${encodeURIComponent(accountId)}/media`);
    const result=await api(endpoint+'?limit=30');
    const items=Array.isArray(result.items)?result.items:[];
    const heading=document.createElement('div');heading.className='meta-media-heading';
    const title=document.createElement('h2');title.textContent='محتوى '+account.platform+' — '+account.account_name;
    const back=document.createElement('button');back.type='button';back.className='btn';back.dataset.action='back-accounts';back.textContent='العودة للحسابات';heading.append(title,back);
    const source=document.createElement('p');source.className='meta-source-note';source.textContent='المصدر: '+(metaMedia?'Meta Graph API':account.platform+' API')+' — العناصر المتاحة حسب صلاحيات حسابك.';
    const toolbar=document.createElement('div');toolbar.className='meta-feed-toolbar';
    const label=document.createElement('label');label.htmlFor='metaMediaFilter';label.textContent='تصفية المحتوى';
    const filter=document.createElement('select');filter.id='metaMediaFilter';filter.className='field-input';
    [['all','كل المحتوى'],['reels','Reels / ريلز'],['videos','كل الفيديوهات'],['images','الصور والألبومات'],['other','منشورات أخرى']].forEach(entry=>{const option=document.createElement('option');option.value=entry[0];option.textContent=entry[1];filter.append(option)});
    const count=document.createElement('span');count.className='meta-media-count';count.setAttribute('aria-live','polite');toolbar.append(label,filter,count);
    const grid=document.createElement('div');grid.className='meta-feed-grid';
    for(const item of items){
      const card=document.createElement('article');card.className='meta-feed-card';
      const type=String(item.media_type||'TEXT').toUpperCase();card.dataset.mediaType=type;
      const frame=document.createElement('div');frame.className='meta-feed-media';
      const kind=type==='REELS'?'ريلز':type==='VIDEO'?'فيديو':(['IMAGE','CAROUSEL_ALBUM'].includes(type)?'صورة / ألبوم':'منشور');
      const mediaUrl=safeHttpsMediaUrl(item.media_url),thumbnailUrl=safeHttpsMediaUrl(item.thumbnail_url);let visual;
      if((type==='VIDEO'||type==='REELS')&&mediaUrl){visual=document.createElement('video');visual.controls=true;visual.playsInline=true;visual.preload='metadata';visual.src=mediaUrl;visual.setAttribute('aria-label',kind);if(thumbnailUrl)visual.poster=thumbnailUrl}
      else if(thumbnailUrl){visual=document.createElement('img');visual.loading='lazy';visual.alt=kind;visual.src=thumbnailUrl}
      else{visual=document.createElement('div');visual.className='meta-no-media';visual.textContent='لا توجد معاينة وسائط متاحة'}
      frame.append(visual);
      const copy=document.createElement('div');copy.className='meta-feed-copy';const metadata=document.createElement('div');metadata.className='meta-feed-meta';
      const badge=document.createElement('span');badge.className='meta-feed-kind';badge.textContent=kind;const date=document.createElement('span');date.textContent=item.timestamp||'';metadata.append(badge,date);
      const caption=document.createElement('p');caption.textContent=item.caption||'بدون وصف نصي';copy.append(metadata,caption);
      const permalink=safeHttpsMediaUrl(item.permalink);if(permalink){const link=document.createElement('a');link.href=permalink;link.target='_blank';link.rel='noopener noreferrer';link.textContent='فتح المنشور الأصلي ↗';copy.append(link)}
      card.append(frame,copy);grid.append(card);
    }
    const empty=document.createElement('section');empty.className='card empty-box';empty.textContent='لم تُرجع المنصة منشورات لهذه الصلاحيات. تحقق من نوع الحساب وصلاحيات Meta.';
    const noMatch=document.createElement('section');noMatch.className='card empty-box hidden';noMatch.textContent='لا توجد عناصر ضمن هذا النوع؛ اختر تصفية أخرى.';
    const applyFilter=()=>{const selected=filter.value;let visible=0;grid.querySelectorAll('.meta-feed-card').forEach(card=>{const type=card.dataset.mediaType||'TEXT';const video=type==='VIDEO'||type==='REELS';const image=type==='IMAGE'||type==='CAROUSEL_ALBUM';const match=selected==='all'||(selected==='reels'&&type==='REELS')||(selected==='videos'&&video)||(selected==='images'&&image)||(selected==='other'&&!video&&!image);card.hidden=!match;if(match)visible++});count.textContent='العناصر: '+visible+' من '+items.length;noMatch.classList.toggle('hidden',items.length===0||visible>0)};
    filter.addEventListener('change',applyFilter);applyFilter();
    if(items.length===0){toolbar.classList.add('hidden');grid.classList.add('hidden')}else{empty.classList.add('hidden')}
    content.replaceChildren(heading,source,toolbar,grid,empty,noMatch);
  }catch(error){const message=document.createElement('section');message.className='card empty-box';message.textContent='تعذر تحميل المحتوى الحقيقي: '+(error&&error.message?error.message:'تحقق من إعداد OAuth والصلاحيات.');const back=document.createElement('button');back.type='button';back.className='btn';back.dataset.action='back-accounts';back.textContent='العودة للحسابات';content.replaceChildren(message,back)}
}

async function renderMedia(){const items=await api('/media?limit=250');$('#pageContent').innerHTML=`${pageHead('مكتبة الوسائط','ملفات مخزنة في مساحة العمل مع تحقق من نوع الملف وحجمه')}<section class="card upload-card"><form id="mediaUploadForm" class="upload-row"><div class="field full"><label for="mediaFile">اختر صورة أو فيديو أو ملف PDF</label><input id="mediaFile" type="file" name="file" accept="image/jpeg,image/png,image/gif,image/webp,video/mp4,video/webm,application/pdf,.jpg,.jpeg,.png,.gif,.webp,.mp4,.webm,.pdf" required><span class="help">صور وPDF حتى 20 ميجابايت، وفيديو حتى 100 ميجابايت. تُخزن الملفات داخل مساحة العمل ولا تكون عامة.</span></div><button class="btn btn-primary" type="submit">رفع الملف</button></form></section><div class="media-grid">${items.length?items.map(x=>`<article class="card media-card"><div class="media-type">${x.media_type.startsWith('image/')?'▧':x.media_type.startsWith('video/')?'▶':'PDF'}</div><div class="media-name" title="${esc(x.original_filename)}">${esc(x.original_filename)}</div><div class="help">${formatBytes(x.size_bytes)} · ${dateOnly(x.created_at)}</div><div class="actions"><button class="btn btn-small" data-media-download="${esc(x.id)}" data-media-name="${esc(x.original_filename)}">تنزيل</button><button class="btn btn-small btn-danger" data-media-delete="${esc(x.id)}">حذف</button></div></article>`).join(''):`<section class="card empty-box"><div class="big">▧</div><b>مكتبة الوسائط فارغة</b><p>ارفع الصور والفيديوهات والملفات التي يحتاجها فريق العمل.</p></section>`}</div>`}
function formatBytes(bytes){if(!bytes)return '0 بايت';const units=['بايت','KB','MB','GB'];let n=Number(bytes),i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return (i===0?Math.round(n):n.toFixed(1))+' '+units[i]}
async function renderTeam(){const members=await api('/team/members');const roles=[['admin','مدير'],['editor','مسؤول محتوى'],['support','خدمة العملاء والمبيعات'],['analyst','محلل']];$('#pageContent').innerHTML=`${pageHead('إدارة الفريق','إضافة أعضاء وتحديد صلاحياتهم وإيقاف وصولهم عند الحاجة','إضافة عضو','new-member')}<div class="notice"><b>الصلاحيات تطبق على الخادم</b>العضو الجديد يبدأ بكلمة مرور مؤقتة ويُطلب منه تغييرها قبل استخدام بقية النظام. شارك كلمة المرور المؤقتة مع العضو عبر قناة آمنة.</div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>العضو</th><th>الصلاحية</th><th>الحالة</th><th>كلمة المرور</th><th>إجراء</th></tr></thead><tbody>${members.map(m=>`<tr><td><b>${esc(m.full_name)}</b><div class="help">${esc(m.email)}</div></td><td>${m.role==='owner'?status('مالك مساحة العمل','good'):`<select class="field-input" data-member-role="${esc(m.id)}" ${currentUser.role==='admin'?'':' '}>${roles.map(([v,l])=>`<option value="${v}" ${v===m.role?'selected':''} ${currentUser.role==='admin'&&v==='admin'?'disabled':''}>${l}</option>`).join('')}</select>`}</td><td>${m.is_active?status('نشط','good'):status('معطّل','bad')}</td><td>${m.must_change_password?status('يلزم تغييرها','warn'):status('محدّثة','muted')}</td><td><div class="actions">${m.role==='owner'?'':`<button class="btn btn-small" data-member-toggle="${esc(m.id)}" data-active="${m.is_active?'1':'0'}">${m.is_active?'تعطيل':'تفعيل'}</button><button class="btn btn-small" data-member-reset="${esc(m.id)}" data-member-name="${esc(m.full_name)}">إعادة ضبط كلمة المرور</button>`}</div></td></tr>`).join('')}</tbody></table></div></section>`}
async function renderSettings(){return renderEnhancedSettings()}
async function newConversation(){const contacts=canReadArea('contacts')?await api('/contacts?limit=250'):[];const channelOptions=platformOptions();const contactOptions=`<option value=\"\">بدون عميل مرتبط</option>`+contacts.map(c=>`<option value=\"${esc(c.id)}\">${esc(c.name)}${c.company?' — '+esc(c.company):''}</option>`).join('');const fields=`<div class=\"form-grid\">${selectField('القناة','channel',channelOptions)}<div class=\"field\"><label>العميل (اختياري)</label><select name=\"contact_id\">${contactOptions}</select></div>${selectField('الحالة','status',optionList([['open','مفتوحة'],['pending','بانتظار المتابعة'],['closed','مغلقة']],'open'))}</div><div class=\"notice\">هذه محادثة داخلية محلية، ولا تنشئ اتصالًا تلقائيًا بالمنصة.</div>`;showModal('إنشاء سجل محادثة',fields,{channel:'WhatsApp',status:'open'},async f=>{await api('/conversations',{method:'POST',body:JSON.stringify({channel:f.get('channel'),contact_id:f.get('contact_id')||null,status:f.get('status')})})})}
function newMember(){const roles=currentUser.role==='owner'?[['admin','مدير'],['editor','مسؤول محتوى'],['support','خدمة العملاء والمبيعات'],['analyst','محلل']]:[['editor','مسؤول محتوى'],['support','خدمة العملاء والمبيعات'],['analyst','محلل']];const fields=`<div class="form-grid">${field('اسم العضو','full_name','text',true,'minlength="2" maxlength="160"')}${field('البريد الإلكتروني','email','email',true)}${field('كلمة مرور مؤقتة (12 حرفًا على الأقل)','temporary_password','password',true,'minlength="12" maxlength="128" autocomplete="new-password"')}${selectField('الدور','role',optionList(roles,'editor'))}</div><div class="notice"><b>تنبيه أمني</b>سيُطلب من العضو تغيير كلمة المرور بعد أول تسجيل دخول.</div>`;showModal('إضافة عضو للفريق',fields,{},async f=>{await api('/team/members',{method:'POST',body:JSON.stringify({full_name:f.get('full_name'),email:f.get('email'),temporary_password:f.get('temporary_password'),role:f.get('role')})})})}
function promptPasswordChange(mandatory){const fields=`<div class="form-grid">${field('كلمة المرور الحالية أو المؤقتة','current_password','password',true,'autocomplete="current-password"')}${field('كلمة المرور الجديدة','new_password','password',true,'minlength="12" maxlength="128" autocomplete="new-password"')}${field('تأكيد كلمة المرور الجديدة','confirm_password','password',true,'minlength="12" maxlength="128" autocomplete="new-password"')}</div><div class="help">استخدم 12 حرفًا على الأقل. تجنّب إعادة استخدام كلمة مرورك في خدمات أخرى.</div>`;showModal(mandatory?'يلزم تغيير كلمة المرور المؤقتة':'تغيير كلمة المرور',fields,{},async f=>{const newPass=String(f.get('new_password')||'');if(newPass!==String(f.get('confirm_password')||''))throw new Error('كلمتا المرور الجديدتان غير متطابقتين');const out=await api('/auth/change-password',{method:'POST',body:JSON.stringify({current_password:f.get('current_password'),new_password:newPass})});token=out.access_token;sessionStorage.setItem('midar_token',token);currentUser=out.user;$('#profileRole').textContent=roleName(currentUser.role);if(mandatory)toast('تم تفعيل حسابك بنجاح');return out},{mandatory})}
async function downloadContacts(){try{const headers={Authorization:'Bearer '+token};const r=await fetch(API+'/exports/contacts.csv',{headers});if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.detail||'تعذر تصدير البيانات')}const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='m-contacts.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('تم تصدير العملاء إلى CSV')}catch(e){toast(e.message)}}
function showModal(title,fields,initial,onSave,options={}){const mandatory=!!options.mandatory;$('#modalRoot').innerHTML=`<div class="modal-bg" id="modalBg"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><h3 id="modalTitle">${esc(title)}</h3>${mandatory?'':`<button class="x" data-action="close-modal">إغلاق</button>`}</div><form id="entityForm"><div class="modal-body">${fields}</div><div class="modal-foot"><button class="btn btn-primary" type="submit">حفظ</button>${mandatory?'':`<button class="btn" type="button" data-action="close-modal">إلغاء</button>`}</div></form></section></div>`;const form=$('#entityForm');Object.entries(initial||{}).forEach(([key,value])=>{const field=form.elements.namedItem(key);if(field&&value!=null){if(field.type==='datetime-local'){field.value=formatLocalInput(value,uiTimezone)}else field.value=value}});form.addEventListener('submit',async e=>{e.preventDefault();const btn=form.querySelector('[type=submit]');btn.disabled=true;btn.textContent='جارٍ الحفظ…';try{await onSave(new FormData(form));$('#modalRoot').innerHTML='';toast('تم حفظ البيانات على الخادم');await loadPage(currentPage)}catch(err){toast(err.message);btn.disabled=false;btn.textContent='حفظ'}});$('#modalBg').addEventListener('click',e=>{if(!mandatory&&e.target.id==='modalBg')$('#modalRoot').innerHTML=''})}
const field=(label,name,type='text',required=false,extra='')=>`<div class="field"><label>${esc(label)}</label><input name="${name}" type="${type}" ${required?'required':''} ${extra}></div>`;const selectField=(label,name,options)=>`<div class="field"><label>${esc(label)}</label><select name="${name}" required>${options}</select></div>`;const textareaField=(label,name)=>`<div class="field full"><label>${esc(label)}</label><textarea name="${name}"></textarea></div>`;const optionList=(options,value)=>options.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${esc(l)}</option>`).join('');
async function newPost(item=null){
  const x=item||{};
  let accounts=[];
  try{accounts=await api('/social-accounts')}catch(e){toast('تعذر تحميل حسابات النشر: '+e.message);return}
  const publishPlatforms=['Facebook','Telegram','X','LinkedIn'];
  const publishAccounts=accounts.filter(a=>publishPlatforms.includes(a.platform)&&a.connection_status==='connected'&&Boolean(a.provider_account_id));
  const accountOptions=`<option value="">اختر حسابًا موصولًا</option>${publishAccounts.map(a=>`<option value="${esc(a.id)}" data-platform="${esc(a.platform)}">${esc(a.platform)} — ${esc(a.account_name)} (${esc(a.handle||'حساب مرتبط')})</option>`).join('')}`;
  const fields=`<div class="form-grid">${field('عنوان المنشور','title','text',true,'maxlength="240"')}${selectField('المنصة','platform',platformOptions())}${selectField('الحالة','status',optionList([['draft','مسودة'],['scheduled','موعد محفوظ داخل المنصة'],['cancelled','ملغى']],x.status||'draft'))}<div class="field full"><label>الحساب الحقيقي للنشر</label><select name="social_account_id">${accountOptions}</select><span class="help">اختر حسابًا متصلًا من المنصة نفسها. النشر متاح حاليًا للنصوص على Facebook وX وLinkedIn وTelegram؛ لا توجد جدولة تلقائية بعد.</span></div><div class="field"><label>موعد النشر (اختياري)</label><input name="scheduled_at" type="datetime-local"><span class="help">هذا الموعد يُحفظ فقط ولا يرسل المنشور تلقائيًا حتى تشغيل خدمة الجدولة الخلفية.</span></div>${textareaField('نص المحتوى','content')}</div>`;
  showModal(item?'تعديل المنشور':'إضافة منشور',fields,{title:x.title,platform:x.platform||'Facebook',status:x.status==='changes_requested'?'draft':(x.status||'draft'),scheduled_at:x.scheduled_at,content:x.content,social_account_id:x.social_account_id||''},async f=>{
    const v=f.get('scheduled_at');
    const body={title:f.get('title'),platform:f.get('platform'),status:f.get('status'),scheduled_at:localInputToIso(v,uiTimezone),content:f.get('content')||'',social_account_id:f.get('social_account_id')||null};
    await api('/posts'+(item?'/'+item.id:''),{method:item?'PUT':'POST',body:JSON.stringify(body)});
  });
  const platformSelect=$('#entityForm [name="platform"]');
  const accountSelect=$('#entityForm [name="social_account_id"]');
  const filterAccounts=()=>{
    if(!platformSelect||!accountSelect)return;
    const selectedPlatform=platformSelect.value;
    for(const option of accountSelect.options){
      if(!option.value)continue;
      const matches=option.dataset.platform===selectedPlatform;
      option.hidden=!matches;
      option.disabled=!matches;
    }
    if(accountSelect.selectedOptions[0]?.dataset.platform && accountSelect.selectedOptions[0].dataset.platform!==selectedPlatform)accountSelect.value='';
  };
  platformSelect?.addEventListener('change',filterAccounts);
  filterAccounts();
}
function newCampaign(item=null){const x=item||{};const fields=`<div class="form-grid">${field('اسم الحملة','name','text',true,'maxlength="200"')}${selectField('الهدف','objective',optionList([['awareness','الوعي بالعلامة'],['engagement','التفاعل'],['leads','جذب العملاء'],['sales','المبيعات'],['traffic','الزيارات'],['other','أخرى']],x.objective||'awareness'))}${selectField('الحالة','status',optionList([['planning','قيد التخطيط'],['active','نشطة'],['paused','متوقفة مؤقتًا'],['completed','مكتملة'],['cancelled','ملغاة']],x.status||'planning'))}${field('الميزانية (₪)','budget','number',false,'min="0" step="0.01" max="1000000000"')}<div class="field"><label>تاريخ البداية</label><input name="start_at" type="datetime-local"></div><div class="field"><label>تاريخ النهاية</label><input name="end_at" type="datetime-local"></div>${textareaField('ملاحظات وخطة الحملة','notes')}</div>`;showModal(item?'تعديل الحملة':'إضافة حملة',fields,{name:x.name,objective:x.objective||'awareness',status:x.status||'planning',budget:x.budget??0,start_at:x.start_at,end_at:x.end_at,notes:x.notes},async f=>{const toIso=n=>localInputToIso(f.get(n),uiTimezone);await api('/campaigns'+(item?'/'+item.id:''),{method:item?'PUT':'POST',body:JSON.stringify({name:f.get('name'),objective:f.get('objective'),status:f.get('status'),budget:Number(f.get('budget')||0),start_at:toIso('start_at'),end_at:toIso('end_at'),notes:f.get('notes')||''})})})}
function newContact(item=null){const x=item||{};const fields=`<div class="form-grid">${field('الاسم الكامل','name','text',true)}${field('الشركة','company')}${field('البريد الإلكتروني','email','email')}${field('رقم الهاتف','phone','tel')}${field('مصدر العميل','source')}${selectField('مرحلة البيع','stage',optionList(Object.entries(stageLabels),x.stage||'new'))}${field('قيمة الفرصة (₪)','value','number',false,'min="0" step="0.01"')}${field('موعد المتابعة','follow_up_at','date')}${textareaField('ملاحظات','notes')}</div>`;showModal(item?'تعديل بيانات العميل':'إضافة عميل',fields,{name:x.name,company:x.company,email:x.email,phone:x.phone,source:x.source||'يدوي',stage:x.stage||'new',value:x.value??0,follow_up_at:x.follow_up_at?String(x.follow_up_at).slice(0,10):'',notes:x.notes},async f=>{const date=f.get('follow_up_at');const body={name:f.get('name'),company:f.get('company')||'',email:f.get('email')||null,phone:f.get('phone')||null,source:f.get('source')||'manual',stage:f.get('stage'),value:Number(f.get('value')||0),follow_up_at:date?localInputToIso(date+'T12:00',uiTimezone):null,notes:f.get('notes')||''};await api('/contacts'+(item?'/'+item.id:''),{method:item?'PUT':'POST',body:JSON.stringify(body)})})}
function newTask(item=null){const x=item||{};const fields=`<div class="form-grid">${field('عنوان المهمة','title','text',true)}${field('المسؤول','assignee')}${selectField('الأولوية','priority',optionList([['low','منخفضة'],['medium','متوسطة'],['high','عالية']],x.priority||'medium'))}${selectField('الحالة','status',optionList([['open','مفتوحة'],['in_progress','قيد التنفيذ'],['done','مكتملة'],['cancelled','ملغاة']],x.status||'open'))}<div class="field"><label>موعد الاستحقاق</label><input name="due_at" type="datetime-local"></div>${textareaField('الوصف','description')}</div>`;showModal(item?'تعديل المهمة':'إضافة مهمة',fields,{title:x.title,assignee:x.assignee,priority:x.priority||'medium',status:x.status||'open',due_at:x.due_at,description:x.description},async f=>{const v=f.get('due_at');const body={title:f.get('title'),assignee:f.get('assignee')||'',priority:f.get('priority'),status:f.get('status'),due_at:localInputToIso(v,uiTimezone),description:f.get('description')||''};await api('/tasks'+(item?'/'+item.id:''),{method:item?'PUT':'POST',body:JSON.stringify(body)})})}
function newAccount(){const fields=`<div class="form-grid">${selectField('المنصة','platform',platformOptions())}${field('اسم الحساب أو الصفحة','account_name','text',true)}${field('المعرّف الظاهر أو اسم المستخدم','handle')}</div><div class="notice" style="margin-top:5px"><b>لا تدخل كلمة المرور أو رموز الوصول</b>هذا النموذج يسجل بيانات تعريفية فقط؛ الاتصال الرسمي سيُنفذ لاحقًا من خلال تفويض آمن.</div>`;showModal('إضافة حساب اجتماعي',fields,{platform:'Facebook'},async f=>{await api('/social-accounts',{method:'POST',body:JSON.stringify({platform:f.get('platform'),account_name:f.get('account_name'),handle:f.get('handle')||''})})})}
$('#pageContent').addEventListener('click',async e=>{const page=e.target.closest('[data-page]');if(page){loadPage(page.dataset.page);return}const act=e.target.closest('[data-action]')?.dataset.action;if(act==='new-conversation'){newConversation();return}if(act==='back-inbox'){loadPage('inbox');return}const opened=e.target.closest('[data-open-conversation]');if(opened){renderConversationDetail(opened.dataset.openConversation);return}const editedCampaign=e.target.closest('[data-edit-campaign]');if(editedCampaign){newCampaign((cache.campaigns||[]).find(x=>x.id===editedCampaign.dataset.editCampaign));return}const deletedCampaign=e.target.closest('[data-delete-campaign]');if(deletedCampaign){if(confirm('هل تريد حذف الحملة نهائيًا؟'))try{await api('/campaigns/'+deletedCampaign.dataset.deleteCampaign,{method:'DELETE'});toast('تم حذف الحملة');loadPage('campaigns')}catch(err){toast(err.message)}return}if(act==='reload'){loadPage(currentPage);return}if(act==='new-post'){newPost();return}if(act==='new-video-draft'){newVideoDraft();return}const ev=e.target.closest('[data-edit-video]');if(ev){newVideoDraft((cache.videoDrafts||[]).find(x=>x.id===ev.dataset.editVideo));return}const pv=e.target.closest('[data-preview-video]');if(pv){previewVideoDraft(pv.dataset.previewVideo);return}const dv=e.target.closest('[data-delete-video]');if(dv){if(confirm('حذف مسودة الفيديو؟'))try{await api('/video-drafts/'+dv.dataset.deleteVideo,{method:'DELETE'});toast('تم حذف المسودة');await loadPage('studio')}catch(err){toast(err.message)}return}const tv=e.target.closest('[data-telegram-verify]');if(tv){if(!confirm('سيتحقق النظام من أن البوت المهيأ على الخادم يستطيع النشر في هذه القناة. هل تريد المتابعة؟'))return;try{const out=await api('/integrations/telegram/verify',{method:'POST',body:JSON.stringify({social_account_id:tv.dataset.telegramVerify})});toast('تم التحقق من قناة Telegram: '+(out.destination.title||out.destination.username||'القناة'));await loadPage('accounts')}catch(err){toast(err.message)}return}const submitReview=e.target.closest('[data-submit-review]');if(submitReview){if(!confirm('إرسال المنشور إلى قائمة المراجعة؟ لن يمكن تعديله حتى يتخذ المراجع قرارًا.'))return;try{await api('/posts/'+submitReview.dataset.submitReview+'/submit-review',{method:'POST'});toast('تم إرسال المنشور للمراجعة');await loadPage('posts')}catch(err){toast(err.message)}return}const approvePost=e.target.closest('[data-approve-post]');if(approvePost){if(!confirm('اعتماد هذا المحتوى؟ سيُسجّل القرار في سجل النشاط.'))return;try{await api('/posts/'+approvePost.dataset.approvePost+'/approve',{method:'POST'});toast('تم اعتماد المحتوى');await loadPage('posts')}catch(err){toast(err.message)}return}const requestChanges=e.target.closest('[data-request-changes]');if(requestChanges){const reviewForm=`<div class="field full"><label for="reviewNote">سبب طلب التعديل</label><textarea id="reviewNote" name="note" required minlength="5" maxlength="1000" rows="5" placeholder="وضّح ما يحتاج إلى تعديل ولماذا…"></textarea><span class="help">ستظهر هذه الملاحظة للمحرر بجانب حالة المنشور.</span></div>`;showModal('طلب تعديل المحتوى',reviewForm,{note:''},async f=>{const note=String(f.get('note')||'').trim();if(note.length<5)throw new Error('اكتب سببًا واضحًا من 5 أحرف على الأقل');await api('/posts/'+requestChanges.dataset.requestChanges+'/request-changes',{method:'POST',body:JSON.stringify({note})})});return}const pp=e.target.closest('[data-publish-post]');if(pp){if(!confirm('سيتم إرسال النص إلى قناة Telegram الحقيقية. تأكد من اختيار القناة والمحتوى الصحيحين. متابعة؟'))return;try{await api('/posts/'+pp.dataset.publishPost+'/publish',{method:'POST'});toast('تم النشر في Telegram بنجاح');await loadPage('posts')}catch(err){toast(err.message);await loadPage('posts')}return}const rd=e.target.closest('[data-resolve-delivery]');if(rd){const resolution=rd.dataset.resolution;const note=window.prompt(resolution==='published'?'تحقق من القناة يدويًا ثم اكتب ملاحظة تؤكد ظهور المنشور:':'تحقق من القناة يدويًا ثم اكتب ملاحظة تؤكد عدم ظهور المنشور:');if(!note||note.trim().length<5){toast('يلزم إدخال ملاحظة تحقق من 5 أحرف على الأقل');return}let providerPostId=null;if(resolution==='published')providerPostId=window.prompt('أدخل معرّف رسالة Telegram إن توفر (اختياري):')||null;try{const out=await api('/posts/'+rd.dataset.resolveDelivery+'/resolve-delivery',{method:'POST',body:JSON.stringify({resolution,note:note.trim(),provider_post_id:providerPostId})});toast(out.status==='published'?'تم تسجيل النشر بعد التحقق اليدوي':'تم تسجيل عدم التسليم بعد التحقق اليدوي');await loadPage('posts')}catch(err){toast(err.message)}return}if(act==='new-campaign'){newCampaign();return}if(act==='new-contact'){newContact();return}if(act==='new-task'){newTask();return}if(act==='new-account'){newAccount();return}if(act==='back-accounts'){loadPage('accounts');return}if(act==='connect-meta'){try{const out=await api('/integrations/meta/connect-url',{method:'POST'});if(!out.authorization_url||!out.authorization_url.startsWith('https://www.facebook.com/'))throw new Error('رابط Meta غير متوقع.');window.location.assign(out.authorization_url)}catch(err){toast(err.message||'تعذر بدء ربط Meta')}return}const remote=e.target.closest('[data-view-remote-media]');if(remote){await renderMetaMedia(remote.dataset.viewRemoteMedia);return}if(act==='new-member'){newMember();return}if(act==='export-contacts'){downloadContacts();return}if(act==='password-change'){promptPasswordChange(false);return}if(act==='save-org'){return}const ep=e.target.closest('[data-edit-post]');if(ep){newPost(cache.posts.find(x=>x.id===ep.dataset.editPost));return}const dp=e.target.closest('[data-delete-post]');if(dp){if(confirm('هل تريد حذف هذا المنشور نهائيًا؟'))try{await api('/posts/'+dp.dataset.deletePost,{method:'DELETE'});toast('تم حذف المنشور');loadPage(currentPage)}catch(err){toast(err.message)}return}const ec=e.target.closest('[data-edit-contact]');if(ec){newContact(cache.contacts.find(x=>x.id===ec.dataset.editContact));return}const dc=e.target.closest('[data-delete-contact]');if(dc){if(confirm('هل تريد حذف ملف العميل؟'))try{await api('/contacts/'+dc.dataset.deleteContact,{method:'DELETE'});toast('تم حذف العميل');loadPage(currentPage)}catch(err){toast(err.message)}return}const et=e.target.closest('[data-edit-task]');if(et){newTask(cache.tasks.find(x=>x.id===et.dataset.editTask));return}const dt=e.target.closest('[data-delete-task]');if(dt){if(confirm('هل تريد حذف هذه المهمة؟'))try{await api('/tasks/'+dt.dataset.deleteTask,{method:'DELETE'});toast('تم حذف المهمة');loadPage(currentPage)}catch(err){toast(err.message)}return}const da=e.target.closest('[data-delete-account]');if(da){if(confirm('إزالة الحساب من قائمة الحسابات في المنصة؟ لن يؤدي ذلك إلى تغيير إعدادات الحساب الأصلي.'))try{await api('/social-accounts/'+da.dataset.deleteAccount,{method:'DELETE'});toast('تمت إزالة الحساب من القائمة');loadPage(currentPage)}catch(err){toast(err.message)}return}const md=e.target.closest('[data-media-delete]');if(md){if(confirm('حذف هذا الملف نهائيًا؟'))try{await api('/media/'+md.dataset.mediaDelete,{method:'DELETE'});toast('تم حذف الملف');loadPage('media')}catch(err){toast(err.message)}return}const mdown=e.target.closest('[data-media-download]');if(mdown){try{const r=await fetch(API+'/media/'+mdown.dataset.mediaDownload+'/download',{headers:{Authorization:'Bearer '+token}});if(!r.ok)throw new Error('تعذر تنزيل الملف');const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=mdown.dataset.mediaName||'m-media-file';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}catch(err){toast(err.message)}return}const mt=e.target.closest('[data-member-toggle]');if(mt){const active=mt.dataset.active==='1';if(!confirm(active?'تعطيل وصول هذا العضو؟':'إعادة تفعيل هذا العضو؟'))return;try{await api('/team/members/'+mt.dataset.memberToggle,{method:'PATCH',body:JSON.stringify({is_active:!active})});toast(active?'تم تعطيل العضو':'تم تفعيل العضو');loadPage('team')}catch(err){toast(err.message)}return}const mr=e.target.closest('[data-member-reset]');if(mr){const fields=`<div class="form-grid">${field('كلمة مرور مؤقتة جديدة','temporary_password','password',true,'minlength="12" maxlength="128"')}</div><div class="notice">سيتم إلغاء الجلسات الحالية للعضو وإلزامه بتغيير كلمة المرور عند الدخول.</div>`;showModal('إعادة ضبط كلمة المرور: '+mr.dataset.memberName,fields,{},async f=>{await api('/team/members/'+mr.dataset.memberReset+'/reset-password',{method:'POST',body:JSON.stringify({temporary_password:f.get('temporary_password')})})});return}if(act==='close-modal')$('#modalRoot').innerHTML=''});
