$('#modalRoot').addEventListener('click', e => { if ((e.target.closest('[data-action=close-modal]') || e.target.id === 'modalBg') && activePreviewObjectUrl) { URL.revokeObjectURL(activePreviewObjectUrl); activePreviewObjectUrl = null; } });
$('#pageContent').addEventListener('change',async e=>{const sel=e.target.closest('[data-contact-stage]');if(sel){const x=cache.contacts.find(c=>c.id===sel.dataset.contactStage);if(!x)return;try{await api('/contacts/'+x.id,{method:'PUT',body:JSON.stringify({...x,stage:sel.value})});toast('تم تحديث مرحلة العميل');await loadPage(currentPage)}catch(err){toast(err.message);sel.value=x.stage}return}const convStatus=e.target.closest('[data-conversation-status]');if(convStatus){const id=convStatus.dataset.conversationStatus;try{const conversations=await api('/conversations');const c=conversations.find(x=>x.id===id);if(!c)throw new Error('المحادثة غير موجودة');await api('/conversations/'+id,{method:'PATCH',body:JSON.stringify({status:convStatus.value,contact_id:c.contact_id})});toast('تم تحديث حالة المحادثة');await renderConversationDetail(id)}catch(err){toast(err.message)}return}const roleSel=e.target.closest('[data-member-role]');if(roleSel){try{await api('/team/members/'+roleSel.dataset.memberRole,{method:'PATCH',body:JSON.stringify({role:roleSel.value})});toast('تم تحديث صلاحية العضو');await loadPage(currentPage)}catch(err){toast(err.message);await loadPage(currentPage)}return}const orgForm=e.target.closest('#orgForm');if(orgForm)return});
$('#pageContent').addEventListener('submit',async e=>{if(e.target.id==='localMessageForm'){e.preventDefault();const form=e.target;const body=String(new FormData(form).get('body')||'').trim();if(!body)return;const btn=form.querySelector('button[type=submit]');btn.disabled=true;try{const saved=await api('/conversations/'+form.dataset.conversationId+'/messages',{method:'POST',body:JSON.stringify({body,direction:'outbound'})});toast(saved?.delivery_status==='sent'?'تم إرسال رد WhatsApp عبر Cloud API.':'تم حفظ السجل محليًا؛ لم يتم إرسال رسالة خارجية');await renderConversationDetail(form.dataset.conversationId)}catch(err){toast(err.message);btn.disabled=false}return}if(e.target.id==='mediaUploadForm'){e.preventDefault();const input=e.target.elements.namedItem('file');if(!input.files.length){toast('اختر ملفًا أولًا');return}const button=e.target.querySelector('button[type=submit]');button.disabled=true;button.textContent='جارٍ الرفع…';try{const fd=new FormData();fd.append('file',input.files[0]);const headers={};if(token)headers.Authorization='Bearer '+token;const response=await fetch(API+'/media',{method:'POST',headers,body:fd});const result=response.status===204?null:await response.json();if(!response.ok)throw new Error(result?.detail||'تعذر رفع الملف');toast('تم رفع الملف إلى التخزين');await loadPage('media')}catch(err){toast(err.message)}finally{button.disabled=false;button.textContent='رفع الملف'}}if(e.target.id==='orgForm'){e.preventDefault();const f=new FormData(e.target);try{const org=await api('/organization',{method:'PATCH',body:JSON.stringify({name:f.get('name'),timezone:f.get('timezone')})});$('#workspaceName').textContent=org.name;currentUser.organization_name=org.name;toast('تم حفظ إعدادات مساحة العمل');await loadPage('settings')}catch(err){toast(err.message)}}});
async function performLogout() {
  const logoutButton = $('#logoutBtn');
  const accountButton = $('#accountLogoutBtn');
  if (logoutButton) logoutButton.disabled = true;
  if (accountButton) accountButton.disabled = true;
  try { if (token) await api('/auth/logout', { method: 'POST' }); } catch (error) { /* local sign-out must still complete */ }
  token = '';
  currentUser = null;
  sessionStorage.removeItem('midar_token');
  if ($('#accountMenu')) { $('#accountMenu').classList.add('hidden'); $('#accountMenuBtn')?.setAttribute('aria-expanded','false'); }
  showAuth(false);
  if (logoutButton) logoutButton.disabled = false;
  if (accountButton) accountButton.disabled = false;
}

function initAccountMenu() {
  const trigger=$('#accountMenuBtn');const menu=$('#accountMenu');
  if(!trigger||!menu||trigger.dataset.initialized==='true')return;
  trigger.dataset.initialized='true';
  const items=()=>[...menu.querySelectorAll('[role="menuitem"]:not([disabled]):not(.hidden)')];
  const closeMenu=(restoreFocus=false)=>{menu.classList.add('hidden');trigger.setAttribute('aria-expanded','false');if(restoreFocus)trigger.focus()};
  const openMenu=(last=false)=>{menu.classList.remove('hidden');trigger.setAttribute('aria-expanded','true');const controls=items();(last?controls[controls.length-1]:controls[0])?.focus()};
  trigger.addEventListener('click',()=>{menu.classList.contains('hidden')?openMenu(false):closeMenu(false)});
  trigger.addEventListener('keydown',event=>{if(event.key!=='ArrowDown'&&event.key!=='ArrowUp')return;event.preventDefault();openMenu(event.key==='ArrowUp')});
  menu.addEventListener('keydown',event=>{const controls=items();if(!controls.length)return;const current=controls.indexOf(document.activeElement);
    if(event.key==='Escape'){event.preventDefault();closeMenu(true)}
    else if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const d=event.key==='ArrowDown'?1:-1;controls[(current+d+controls.length)%controls.length].focus()}
    else if(event.key==='Home'){event.preventDefault();controls[0].focus()}
    else if(event.key==='End'){event.preventDefault();controls[controls.length-1].focus()}
  });
  document.addEventListener('click',event=>{if(!event.target.closest('.account-menu-wrap'))closeMenu(false)});
  const logoutButton = $('#accountLogoutBtn');
  if (logoutButton) logoutButton.addEventListener('click', performLogout);
  const installButton = $('#installAppBtn');
  if (installButton) {
    const isInstalled = () => window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
    const isAppleMobile = () => /iPhone|iPad|iPod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
    let deferredInstallPrompt = null;
    const updateInstallVisibility = () => installButton.classList.toggle('hidden', isInstalled());
    window.addEventListener('beforeinstallprompt', event => { event.preventDefault(); deferredInstallPrompt = event; updateInstallVisibility(); });
    window.addEventListener('appinstalled', () => { deferredInstallPrompt = null; installButton.classList.add('hidden'); toast('تم تثبيت M على هذا الجهاز'); });
    installButton.addEventListener('click', async () => {
      closeMenu(false);
      if (isInstalled()) { installButton.classList.add('hidden'); return; }
      if (deferredInstallPrompt) {
        const promptEvent = deferredInstallPrompt; deferredInstallPrompt = null;
        try {
          await promptEvent.prompt();
          const outcome = await promptEvent.userChoice;
          if (outcome?.outcome === 'accepted') toast('بدأ تثبيت M على الجهاز');
          else toast('يمكنك تثبيت M لاحقًا من قائمة المتصفح');
        } catch { toast('افتح قائمة المتصفح واختر «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية»', 6500); }
        updateInstallVisibility();
        return;
      }
      if (isAppleMobile()) toast('على iPhone أو iPad: افتح M في Safari، ثم «مشاركة» ← «إضافة إلى الشاشة الرئيسية».', 8500);
      else toast('من قائمة المتصفح اختر «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية» إذا كان الخيار متاحًا.', 7500);
    });
    updateInstallVisibility();
  }
  const createPostButton = $('#globalCreatePostBtn');
  if (createPostButton) createPostButton.addEventListener('click', () => {
    if (!currentUser || !canWriteArea('posts')) { toast('لا تملك صلاحية إنشاء المحتوى'); return; }
    newPost();
  });
}

initAccountMenu();

boot();
